var DeviceHealth = function DeviceHealth(user_id) {

    this.user_id = user_id;

    this.labels = this.getMetricLabelMaps();
    this.getDH();
};

DeviceHealth.TN_CONFIG = 'x_mukl_dh_config';

//------------------------------------------------
// Static functions (Inbound REST handlers)
//------------------------------------------------

/**
 * Provide the set of dex scores for the current logged in user
 *
 * @param {sn_ws_int.RESTAPIRequest} -request,
 * @param {sn_ws_int.RESTAPIResponse} - response
 */
DeviceHealth.provideDexScores = function provideDexScores(request, response, version) {

    var user, api, resp = {
        status: 200,
        data: {}
    };

    //if ( version == 'v2' ) {
    user = new dhUser();
    resp.data = user.getMetricItems();
    /*} else {
    	api = new DHAPI();
    	resp = api.dex_scores;
    }*/

    response.setStatus(resp.status);
    response.setContentType('application/json');

    var writer = response.getStreamWriter();
    writer.writeString(JSON.stringify(resp));
};

